def occurance_substring(text: str, pattern: str):
    if not pattern:
        return None

    positions = [i for i in range(len(text) - len(pattern) + 1) if text.startswith(pattern, i)]

    if not positions:
        return None

    return (pattern, *positions)

# Test case
assert occurance_substring('python programming, python language', 'python') == ('python', 0, 20)
```

